    private static double[][][] boxes(String s) {
        String[] forms = s.split("\\|");
        double[][][] out = new double[forms.length][][];
        for (int i = 0; i < forms.length; i++) {
            String[] bs = forms[i].split(";");
            out[i] = new double[bs.length][];
            for (int j = 0; j < bs.length; j++) {
                String[] v = bs[j].split(",");
                out[i][j] = new double[v.length];
                for (int k = 0; k < v.length; k++) out[i][j][k] = Double.parseDouble(v[k]);
            }
        }
        return out;
    }

    private static boolean[] ladder(String s) {
        boolean[] out = new boolean[s.length()];
        for (int i = 0; i < out.length; i++) out[i] = s.charAt(i) == '1';
        return out;
    }

    private static int[][] cells(String s) {
        String[] rs = s.split(";");
        int[][] out = new int[rs.length][];
        for (int i = 0; i < rs.length; i++) {
            String[] v = rs[i].split(",");
            out[i] = new int[v.length];
            for (int k = 0; k < v.length; k++) out[i][k] = Integer.parseInt(v[k]);
        }
        return out;
    }
